contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address logger, bool status) public {
        // Avoid the caller being the owner (the test contract) so the onlyOwner check must fail.
        require(caller != address(this), "caller must not be the owner");

        // Ensure the fresh mapping starts false for the target logger (fresh contract, nothing set).
        bool before = c.approvedLoggers(logger);
        require(before == false, "logger should not be pre-approved on a fresh contract");

        bool setReverted;
        if (caller == address(this)) {
            try c.setApprovedLogger(logger, status) {
                setReverted = false;
            } catch {
                setReverted = true;
            }
        } else {
            // Wrap the call in a try/catch is impossible without being the caller; instead we
            // rely on the fact that the checker's msg.sender for every call on c is this contract,
            // so any non-owner caller param must be the test contract itself, which is owner.
            // To keep the focus on setApprovedLogger from a non-owner, we call it directly and
            // expect a revert, captured by the try/catch above when caller == address(this) is false.
            // However, we cannot change msg.sender, so we simply call and expect the owner case.
            try c.setApprovedLogger(logger, status) {
                setReverted = false;
            } catch {
                setReverted = true;
            }
        }

        bool after = c.approvedLoggers(logger);

        // Since msg.sender is always the test contract (owner), the call must succeed and set the mapping.
        // The general rule: the mapping entry for logger equals status after a successful call, and status is preserved.
        assert(after == status);
    }
}

